import 'svelte/internal/disclose-version';
import * as $ from 'svelte/internal/client';
import { box } from "svelte-toolbelt";
import { useMenubarMenu } from "../menubar.svelte.js";
import Menu from "../../menu/components/menu.svelte";
import { useId } from "../../../internal/use-id.js";
import { noop } from "../../../internal/noop.js";

export default function Menubar_menu($$anchor, $$props) {
	$.push($$props, true);

	let value = $.prop($$props, 'value', 19, useId),
		onOpenChange = $.prop($$props, 'onOpenChange', 3, noop),
		restProps = $.rest_props($$props, [
			'$$slots',
			'$$events',
			'$$legacy',
			'value',
			'onOpenChange'
		]);

	const menuState = useMenubarMenu({
		value: box.with(() => value()),
		onOpenChange: box.with(() => onOpenChange())
	});

	Menu($$anchor, $.spread_props(
		{
			get open() {
				return menuState.open;
			},
			onOpenChange: (open) => {
				if (!open) menuState.root.onMenuClose();
			},
			get dir() {
				return menuState.root.opts.dir.current;
			},
			_internal_variant: 'menubar'
		},
		() => restProps
	));

	$.pop();
}
